// ================================================================ deck 1 visuals (t01–t03)
// Title: the pendant curve x^3 + y^3 = 9 with its tangent at (1, 2).
const Fp = (x, y) => x ** 3 + y ** 3 - 9;
must(Math.abs(Fp(1, 2)) < 1e-12 && close(islope(Fp, 1, 2), -0.25), 'pendant slope');
const pTitle = plot({ x: [-2, 3], y: [0, 3.5], fns: [{ expr: '(9 - x^3)^(1/3)', label: '$x^3 + y^3 = 9$', domain: [-2, 2] }, { expr: '-0.25x + 2.25', label: 'tangent at $(1, 2)$' }], pts: [[1, 2, '(1, 2)']] }, 'Graph of the curve x cubed plus y cubed equals 9 for x from minus 2 to 2, falling gently, with its tangent line at the point (1, 2), which has slope minus one quarter.', 'Slope $-\\dfrac14$ at $(1, 2)$ without solving for $y$.');
const route1 = flow('LR', [['i', 'Implicit curves'], ['p', 'Parametric form'], ['w', 'One function with respect to another'], ['c', 'Choosing a method']], [['i', 'p'], ['p', 'w'], ['w', 'c']], 'Route map of Part 1: implicit curves, then parametric form, then differentiating one function with respect to another, then choosing the right method.', 'Part 1 at a glance.');
const formsTable = table(['Form', 'Example', 'Is $y$ isolated?'], [['Explicit', '$y = x^2 - 3x$', 'yes'], ['Implicit', '$x^2y + y^3 = 10$', 'no'], ['Parametric', '$x = 2t + 1,\\ y = t^3$', 'both depend on $t$']], 'Table of three ways to describe a curve: explicit form such as y equals x squared minus 3 x; implicit form such as x squared y plus y cubed equals 10, where y is not isolated; parametric form where both x and y depend on a parameter t.', 'Three ways to describe the same kind of curve.');
const implicitSteps = flow('TB', [['a', 'Differentiate every term with respect to $x$'], ['b', 'Each $y$-term gains a factor $\\dfrac{dy}{dx}$ (chain rule)'], ['c', 'Collect the $\\dfrac{dy}{dx}$ terms on one side'], ['d', 'Divide to isolate $\\dfrac{dy}{dx}$']], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Flow of the implicit method: differentiate every term with respect to x; every term containing y gains a factor dy by dx; collect those terms on one side; divide to isolate dy by dx.', 'Four steps, every time.');
// Worked example 1: x^2 + 2xy + 3y^2 = 6 at (1, 1).
const F1 = (x, y) => x * x + 2 * x * y + 3 * y * y - 6;
const we1Slope = islope(F1, 1, 1);
must(Math.abs(F1(1, 1)) < 1e-12 && close(we1Slope, -0.5), 'we1 slope -1/2');
must(close(branch(F1, 1)(1.5), (-1.5 + sq(18 - 2 * 2.25)) / 3), 'we1 explicit branch');
const pWe1 = plot({ x: [-3, 3], y: [-0.5, 2], fns: [{ expr: '(-x + sqrt(18 - 2x^2))/3', label: 'upper branch of $x^2 + 2xy + 3y^2 = 6$', domain: [-3, 3] }, { expr: '-0.5x + 1.5', label: 'tangent at $(1, 1)$' }], pts: [[1, 1, '(1, 1)']] }, 'Upper branch of the oval x squared plus 2 x y plus 3 y squared equals 6, drawn from x equals minus 3 to 3, with its tangent at (1, 1) sloping down with gradient minus one half.', 'Worked example 1: slope $-\\dfrac12$ at $(1, 1)$.');
// Horizontal tangent on the circle x^2 + y^2 + 4x - 2y = 20 (centre (-2, 1), radius 5).
const Fc = (x, y) => x * x + y * y + 4 * x - 2 * y - 20;
must(Math.abs(Fc(-2, 6)) < 1e-12 && Math.abs(islope(Fc, -2, 6)) < 1e-9, 'top of circle');
const pCircle = plot({ x: [-8, 4], y: [-1, 7.5], fns: [{ expr: '1 + sqrt(25 - (x + 2)^2)', label: 'upper half of the circle', domain: [-7, 3] }], hlines: undefined, pts: [[-2, 6, '(−2, 6)']] }, 'Upper half of the circle x squared plus y squared plus 4 x minus 2 y equals 20, centre (minus 2, 1) and radius 5. The highest point is (minus 2, 6), where the tangent is horizontal.', 'The top point: numerator of $\\dfrac{dy}{dx}$ is zero there.');
pCircle.spec.hlines = [{ y: 6, label: '$y = 6$', dashed: true }];
const tangentTable = table(['Tangent', 'Condition on $\\dfrac{dy}{dx} = \\dfrac{N}{D}$', 'Example on the circle'], [['Horizontal', '$N = 0$, $D \\ne 0$', '$(-2, 6)$ and $(-2, -4)$'], ['Vertical', '$D = 0$, $N \\ne 0$', '$(3, 1)$ and $(-7, 1)$']], 'Table: a horizontal tangent needs the numerator of dy by dx to be zero; a vertical tangent needs the denominator to be zero. On the circle with centre (minus 2, 1) and radius 5, the horizontal tangents are at (minus 2, 6) and (minus 2, minus 4), the vertical ones at (3, 1) and (minus 7, 1).', 'Read the fraction, not just its value.');
must([[-2, 6], [-2, -4], [3, 1], [-7, 1]].every(([x, y]) => Math.abs(Fc(x, y)) < 1e-12), 'tangent table points on circle');
// Parametric: nodal cubic x = t^2 - 1, y = t^3 - t.
const Xn = (t) => t * t - 1, Yn = (t) => t ** 3 - t;
const nodeT = [-1.5, -1, -0.5, 0, 0.5, 1, 1.5];
const paramTable = table(['$t$', ...nodeT.map((t) => M(fx(t)))], [['$x = t^2 - 1$', ...nodeT.map((t) => M(fx(Xn(t))))], ['$y = t^3 - t$', ...nodeT.map((t) => M(fx(Yn(t))))]], 'Table of the parametric curve x equals t squared minus 1, y equals t cubed minus t, for t from minus 1.5 to 1.5 in steps of one half. At t equals minus 1 and t equals 1 the curve passes through the same point (0, 0).', 'Two values of $t$ give the same point $(0, 0)$: the curve crosses itself.');
const series = [];
for (let k = 0; k <= 60; k++) { const t = -1.55 + (3.1 * k) / 60; series.push([+Xn(t).toFixed(4), +Yn(t).toFixed(4)]); }
const pNode = plot({ x: [-1.5, 1.5], y: [-2, 2], series: [{ label: '$x = t^2 - 1,\\ y = t^3 - t$', points: series, kind: 'line' }], pts: [[0, 0, '(0, 0)'], [-1, 0, '(−1, 0)']] }, 'Graph of the parametric curve x equals t squared minus 1, y equals t cubed minus t: a loop on the left between (minus 1, 0) and (0, 0), crossing itself at the origin, with two branches going off to the right.', 'A curve that is easier to describe with a parameter.');
must(close(pslope(Xn, Yn, 1), 1) && close(pslope(Xn, Yn, -1), -1), 'two tangents at the node');
// Worked example 2: x = 2t^2, y = 4t.
