// Worked example 3: ellipse x = 5 cos t, y = 2 sin t at t = pi/4.
const we3 = pslope((t) => 5 * Co(t), (t) => 2 * S(t), P / 4);
must(close(we3, -0.4), 'we3 slope -2/5');
