const pWe3 = plot({ x: [-6, 6], y: [-0.5, 3], fns: [{ expr: '2sqrt(1 - x^2/25)', label: 'upper half of $\\dfrac{x^2}{25} + \\dfrac{y^2}{4} = 1$', domain: [-5, 5] }], pts: [[px3, +(2 * sq(1 - (px3 * px3) / 25)).toFixed(6), 'P']] }, 'Upper half of the ellipse traced by x equals 5 cos t and y equals 2 sin t, from (minus 5, 0) over the top point (0, 2) to (5, 0). The point P at t equals pi by 4 is marked on the right half, where the slope is minus two fifths.', 'Worked example 3: slope $-\\dfrac{2}{5}$ at $t = \\dfrac{\\pi}{4}$.');
must(close(py3, 2 * sq(1 - (px3 * px3) / 25)), 'P on ellipse');
const wrtFlow = flow('LR', [['u', '$u = u(x)$'], ['v', '$v = v(x)$'], ['r', '$\\dfrac{du}{dv} = \\dfrac{du/dx}{dv/dx}$']], [['u', 'r'], ['v', 'r']], 'Flow: to differentiate u with respect to v, when both are functions of x, divide du by dx by dv by dx.', 'Both functions depend on the same $x$.');
// Worked example 4: d(sin^2 x)/d(cos x) = -2 cos x.
const we4xs = [P / 6, P / 4, P / 3];
