const we4Table = table(['$x$', ...we4xs.map((_, i) => ['$\\dfrac{\\pi}{6}$', '$\\dfrac{\\pi}{4}$', '$\\dfrac{\\pi}{3}$'][i])], [['ratio of derivatives (numeric)', ...we4xs.map((x) => M(fx(wrt((s) => S(s) ** 2, Co, x))))], ['$-2\\cos x$', ...we4xs.map((x) => M(fx(-2 * Co(x))))]], 'Table for worked example 4: the ratio of the derivative of sine squared x to the derivative of cos x, computed numerically at pi by 6, pi by 4 and pi by 3, matches minus 2 cos x: about minus 1.7321, minus 1.4142 and minus 1.', 'A numerical check of the answer $-2\\cos x$.');
const methodTable = table(['You see', 'Use'], [['$x$ and $y$ mixed, $y$ not isolated', 'implicit differentiation'], ['$x$ and $y$ both given by $t$ or $\\theta$', 'parametric: $\\dfrac{dy/dt}{dx/dt}$'], ['"differentiate $u$ with respect to $v$"', '$\\dfrac{du/dx}{dv/dx}$'], ['variable in base **and** exponent', 'logarithmic differentiation (Part 2)']], 'Table for choosing a method: mixed x and y means implicit differentiation; x and y given by a parameter means divide dy by dt by dx by dt; differentiate u with respect to v means divide their derivatives; a variable in both base and exponent needs logarithms.', 'Read the form first, then choose.');
const summary1 = flow('LR', [['i', 'Implicit: chain rule on every $y$-term'], ['p', 'Parametric: $\\dfrac{dy}{dx} = \\dfrac{dy/dt}{dx/dt}$'], ['w', 'With respect to another: $\\dfrac{du/dx}{dv/dx}$']], [['i', 'p'], ['p', 'w']], 'Summary flow of Part 1: implicit differentiation uses the chain rule on every y term; parametric slope is dy by dt over dx by dt; differentiating u with respect to v divides du by dx by dv by dx.', 'Part 1 in one line.');
const tips1 = table(['Question type', 'How marks are given'], [['Implicit slope (2–3)', 'differentiation 1, collecting terms 1, value at the point 1'], ['Parametric (2)', 'both rates 1, quotient 1'], ['With respect to another (2–3)', 'both derivatives, then the ratio; a substitution earns method marks'], ['Horizontal or vertical tangent', 'set numerator or denominator to zero and check the point lies on the curve']], 'Exam tips table: an implicit slope earns marks for differentiating, collecting terms and the value; a parametric slope for both rates and the quotient; differentiating one function with respect to another for both derivatives and the ratio; tangent questions for setting numerator or denominator to zero and checking the point.', 'ISC marking follows the steps.');

// ================================================================ deck 2 visuals (t04–t05)
const pXX = plot({ x: [0, 2.5], y: [0, 4], fns: [{ expr: 'x^x', label: '$y = x^{x}$', domain: [0.05, 2.5] }], pts: [[1, 1, '(1, 1)'], [2, 4, '(2, 4)']] }, 'Graph of y equals x to the power x for x from 0.05 to 2.5: it dips to a lowest value a little below 0.7 near x equals 0.37, passes through (1, 1) and rises steeply through (2, 4).', 'Neither the power rule nor the exponential rule fits $x^{x}$.');
must(close(D((x) => x ** x, 1 / Math.E), 0, 1e-6) && Math.abs(Math.exp(-1 / Math.E) - 0.6922) < 1e-4, 'minimum of x^x near 1/e');
const goals2 = flow('LR', [['v', 'Variable powers'], ['s', 'Sums of such powers'], ['t', 'Towers'], ['q', 'Long products and quotients'], ['d', 'Second derivatives']], [['v', 's'], ['s', 't'], ['t', 'q'], ['q', 'd']], 'Route map of Part 2: variable powers, sums of variable powers, towers of powers, long products and quotients, then second-order derivatives.', 'Part 2 at a glance.');
const whyLogs = table(['Function', 'Why logs help'], [['$x^{x}$, $(\\log x)^{x}$', 'variable base **and** variable exponent'], ['$\\dfrac{(x + 1)^5(x - 2)^3}{(x + 4)^2}$', 'a long product and quotient becomes a sum'], ['$x^{x^{x}}$', 'a tower: take logs twice']], 'Table of when logarithmic differentiation helps: a variable base and a variable exponent, such as x to the x; a long product and quotient, which logs turn into a sum; and a tower of powers, which needs logs twice.', 'Logs turn powers into products and products into sums.');
const logSteps = flow('TB', [['a', 'Write $y = f(x)^{g(x)}$'], ['b', '$\\log y = g(x)\\log f(x)$'], ['c', 'Differentiate: $\\dfrac{1}{y}\\dfrac{dy}{dx} = \\dots$'], ['d', 'Multiply back by $y$']], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Flow of logarithmic differentiation: write y as f of x to the power g of x; take logs to get g of x times log f of x; differentiate, giving one over y times dy by dx on the left; multiply back by y.', 'The last step is the one students forget.');
// Worked example 5: y = x^(x^2), dy/dx = x^(x^2)(2x log x + x); at x = 2: 16(4 log 2 + 2).
const y5 = (x) => x ** (x * x);
must(sameD(y5, (x) => y5(x) * (2 * x * L(x) + x), [0.7, 1.5, 2]), 'we5 derivative');
const we5Value = 16 * (4 * L(2) + 2);
must(close(D(y5, 2), we5Value), 'we5 value');
const we5Table = table(['Step', 'Result'], [['Take logs', '$\\log y = x^2\\log x$'], ['Differentiate', '$\\dfrac{1}{y}\\dfrac{dy}{dx} = 2x\\log x + x$'], ['Multiply back', '$\\dfrac{dy}{dx} = x^{x^2}(2x\\log x + x)$'], ['At $x = 2$', `$16(4\\log 2 + 2) \\approx ${fx(we5Value, 2)}$`]], `Table for worked example 5, y equals x to the power x squared: log y equals x squared log x; one over y times dy by dx equals 2 x log x plus x; so dy by dx is x to the x squared times that bracket, about ${fx(we5Value, 2)} at x equals 2.`, 'Computed and checked numerically.');
const sumTable = table(['Term', 'Treat it as', 'Derivative'], [['$u = x^{x}$', '$\\log u = x\\log x$', '$x^{x}(1 + \\log x)$'], ['$v = 2^{x}$', 'exponential rule', '$2^{x}\\log 2$'], ['$y = u + v$', 'add the two', '$x^{x}(1 + \\log x) + 2^{x}\\log 2$']], 'Table showing how to differentiate a sum such as x to the x plus 2 to the x: take logs of each term separately, find each derivative, then add. Never take the log of the whole sum.', 'Split first, then take logs term by term.');
