must(close(D(y6, 1), we6Value), 'we6 value');
const we6Table = table(['Quantity at $x = 1$', 'Value'], [['$y = (x^2 + 1)^{x}$', '$2$'], ['$\\log(x^2 + 1) + \\dfrac{2x^2}{x^2 + 1}$', '$\\log 2 + 1$'], ['$\\dfrac{dy}{dx}$', `$2(\\log 2 + 1) \\approx ${fx(we6Value, 2)}$`]], `Table for worked example 6 at x equals 1: y equals 2, the bracket is log 2 plus 1, so dy by dx is 2 times log 2 plus 1, about ${fx(we6Value, 2)}.`, 'Multiply the bracket by $y$.');
// Tower iteration table for x = 1.2.
const towerRows = [];
{ let y = 1; for (let k = 1; k <= 6; k++) { y = 1.2 ** y; towerRows.push([M(k), M(fx(y))]); } }
const towerTable = table(['Step $k$', '$y_k = 1.2^{\\,y_{k - 1}}$'], towerRows, `Table iterating y equals 1.2 to the power y from y equals 1: the values settle down towards about ${fx(tower(1.2), 3)}, the value of the endless tower at x equals 1.2.`, `The endless tower settles at $y \\approx ${fx(tower(1.2), 3)}$, and then $y = 1.2^{y}$.`);
