const secondFlow = flow('TB', [['p', 'Parametric: find $\\dfrac{dy}{dx}$ in $t$'], ['d', 'Differentiate it with respect to $t$'], ['q', 'Divide by $\\dfrac{dx}{dt}$'], ['i', 'Implicit: differentiate the equation for $y\'$ again, then substitute $y\'$']], [['p', 'd'], ['d', 'q']], 'Flow for second derivatives: for a parametric curve, find dy by dx in terms of t, differentiate it with respect to t, then divide by dx by dt. For an implicit curve, differentiate the equation for y dash again and substitute y dash.', 'The extra division by $\\dfrac{dx}{dt}$ is the step most often missed.');
